    best=None
    for s0 in range(15):
        rng=np.random.default_rng(s0)
        x0=np.array(p0)*np.exp(rng.normal(0,0.7,len(p0)))
        try:
            r=least_squares(lambda p: fn(p)-dA_dt, x0)
